const raw = $input.first().json.stdout;
const parsed = JSON.parse(raw);
return [{ json: { html: parsed.html, statusCode: parsed.statusCode, url: parsed.url } }];

const data = $input.first().json;
const parseResponse = $('Parse Response').first().json;
const url = parseResponse.url || 'https://www.bachhoaxanh.com';
const statusCode = parseResponse.statusCode || 200;

// Count stats
const totalLinks = (data.links || []).length;
const internalLinks = (data.links || []).filter(l => l && (l.startsWith('/') || l.includes('bachhoaxanh.com'))).length;
const externalLinks = totalLinks - internalLinks;
const totalImages = (data.images || []).length;
const totalImagesWithAlt = (data.imagesAlt || []).length;
const wordCount = (data.bodyText || '').split(/\s+/).filter(w => w.length > 0).length;

return [{
  json: {
    url: url,
    status_code: statusCode,
    title: data.title || null,
    title_length: (data.title || '').length,
    meta_description: data.metaDescription || null,
    meta_description_length: (data.metaDescription || '').length,
    meta_keywords: data.metaKeywords || null,
    og_title: data.ogTitle || null,
    og_description: data.ogDescription || null,
    og_image: data.ogImage || null,
    og_url: data.ogUrl || null,
    canonical_url: data.canonical || null,
    favicon: data.favicon || null,
    viewport: data.viewport || null,
    charset: data.charset || null,
    robots_meta: data.robots || null,
    h1_tags: JSON.stringify(data.h1 || []),
    h1_count: (data.h1 || []).length,
    h2_tags: JSON.stringify(data.h2 || []),
    h2_count: (data.h2 || []).length,
    h3_tags: JSON.stringify(data.h3 || []),
    h3_count: (data.h3 || []).length,
    total_links: totalLinks,
    internal_links: internalLinks,
    external_links: externalLinks,
    total_images: totalImages,
    images_with_alt: totalImagesWithAlt,
    images_without_alt: totalImages - totalImagesWithAlt,
    word_count: wordCount,
    links_json: JSON.stringify((data.links || []).slice(0, 500)),
    images_json: JSON.stringify((data.images || []).slice(0, 200)),
    crawled_at: new Date().toISOString()
  }
}];

const inserted = $input.first().json;
const crawlData = $('Transform Data').first().json;

return [{
  json: {
    success: true,
    message: 'Crawl completed and saved to PostgreSQL',
    data: {
      id: inserted.id,
      url: crawlData.url,
      title: crawlData.title,
      title_length: crawlData.title_length,
      meta_description: crawlData.meta_description,
      meta_description_length: crawlData.meta_description_length,
      h1_count: crawlData.h1_count,
      h2_count: crawlData.h2_count,
      h3_count: crawlData.h3_count,
      total_links: crawlData.total_links,
      internal_links: crawlData.internal_links,
      external_links: crawlData.external_links,
      total_images: crawlData.total_images,
      images_with_alt: crawlData.images_with_alt,
      images_without_alt: crawlData.images_without_alt,
      word_count: crawlData.word_count,
      crawled_at: crawlData.crawled_at
    }
  }
}];
